html:
{%- set donor = frappe.db.get_value(
	"Donor",
	doc.get("donor_name"),
	["customer_name", "primary_address", "customer_primary_address"],
	as_dict=True
) if doc.get("donor_name") else {} -%}

{%- set donor_display_name = doc.get("name_on_donation_slip") or donor.get("customer_name") or doc.get("donor_name") or "-" -%}
{%- set donor_address = doc.get("donor_primary_address") or donor.get("primary_address") -%}
{%- set primary_address_name = donor.get("customer_primary_address") -%}
{%- set address_details = frappe.db.get_value(
	"Address",
	primary_address_name,
	["address_line1", "address_line2", "city"],
	as_dict=True
) if (not donor_address and primary_address_name) else {} -%}

{%- set currency = doc.get("currency") or frappe.db.get_value("Company", doc.get("company"), "default_currency") or "PKR" -%}
{%- set amount = doc.get("donation_amount") or doc.get("total_donation") or doc.get("paid_amount") or 0 -%}
{%- set beneficiary_count = doc.get("sponsored_student_count") or doc.get("total_sponsored_beneficiaries") -%}
{%- set remarks = doc.get("remarks") or doc.get("remark") or "No Remarks" -%}
{%- set purpose_rows = doc.get("purpose_details") or [] -%}

<style>
@page {
	size: A4 portrait;
	margin: 0;
}

.print-format {
	padding: 0 !important;
	margin: 0 !important;
	background: #fff;
	color: #20242a;
	font-family: "Times New Roman", Georgia, serif;
	font-size: 9pt;
	line-height: 1.25;
}

.donation-receipt-half-page {
	width: 210mm;
	height: 148mm;
	padding: 7mm 10mm;
	margin: 0 auto;
	overflow: hidden;
	page-break-inside: avoid;
	break-inside: avoid;
}

.letter-head {
	max-height: 25mm;
	margin-bottom: 3mm;
	overflow: hidden;
}

.letter-head img {
	max-height: 25mm !important;
	width: auto !important;
	object-fit: contain;
}

.receipt-content {
	margin-top: 3mm;
}

.receipt-columns,
.receipt-fields {
	width: 100%;
	border: 0 !important;
	border-collapse: collapse;
	table-layout: fixed;
}

.receipt-columns td,
.receipt-fields td {
	border: 0 !important;
	vertical-align: top;
}

.receipt-column {
	width: 50%;
}

.receipt-column-left {
	padding-right: 8mm !important;
}

.receipt-column-right {
	padding-left: 8mm !important;
}

.receipt-fields td {
	padding: 1.55mm 0 !important;
	line-height: 1.25;
}

.receipt-label,
.receipt-label-wrap {
	width: 32%;
	padding-right: 2.5mm !important;
	font-weight: 700;
	white-space: nowrap;
}

.receipt-label-wrap {
	white-space: normal;
	word-break: break-word;
}

.receipt-value {
	width: 68%;
	word-wrap: break-word;
}

.receipt-value-strong {
	font-size: 9.5pt;
	font-weight: 700;
}

.receipt-amount {
	font-size: 10.5pt;
	font-weight: 700;
}

.receipt-small {
	font-size: 8pt;
	line-height: 1.25;
}

.receipt-purpose {
	font-size: 8.5pt;
}

.text-center {
	text-align: center;
}

@media screen {
	.print-format {
		width: 210mm;
		min-height: 148mm;
	}

	.donation-receipt-half-page {
		box-shadow: 0 0 0 1px #ddd;
	}
}
</style>

<div class="donation-receipt-half-page">
	{% if letter_head and not no_letterhead %}
		<div class="letter-head">{{ letter_head }}</div>
	{% endif %}

	{% if doc.docstatus == 0 %}
		<div class="text-center"><strong>DRAFT</strong></div>
	{% elif doc.docstatus == 2 %}
		<div class="text-center"><strong>CANCELLED</strong></div>
	{% endif %}

	<div class="receipt-content">
		<table class="receipt-columns">
			<tbody>
				<tr>
					<td class="receipt-column receipt-column-left">
						<table class="receipt-fields">
							<tbody>
								<tr>
									<td class="receipt-label">Date:</td>
									<td class="receipt-value">
										{{ frappe.utils.formatdate(doc.get("donation_posting_date") or doc.get("posting_date"), "dd-MM-yyyy") }}
									</td>
								</tr>

								<tr>
									<td class="receipt-label">Received From:</td>
									<td class="receipt-value receipt-value-strong">{{ donor_display_name }}</td>
								</tr>

								<tr>
									<td class="receipt-label">Address:</td>
									<td class="receipt-value receipt-small">
										{% if donor_address %}
											{{ donor_address }}
										{% elif address_details %}
											{{ address_details.get("address_line1") or "" }}
											{% if address_details.get("address_line2") %}, {{ address_details.get("address_line2") }}{% endif %}
											{% if address_details.get("city") %}, {{ address_details.get("city") }}{% endif %}
										{% else %}
											-
										{% endif %}
									</td>
								</tr>

								<tr>
									<td class="receipt-label">Ph.:</td>
									<td class="receipt-value">{{ doc.get("donor_phone_number") or "-" }}</td>
								</tr>

								<tr>
									<td class="receipt-label">Donation For:</td>
									<td class="receipt-value receipt-purpose">
										{% if purpose_rows %}
											{% for row in purpose_rows %}
												{{ row.get("donation_type") or row.get("donation_category") or "" }}
												{% if row.get("donation_purpose") %}
													- {{ row.get("donation_purpose") }}
												{% elif row.get("purpose_path") %}
													- {{ row.get("purpose_path") }}
												{% endif %}
												{% if not loop.last %}<br>{% endif %}
											{% endfor %}
										{% else %}
											{{ doc.get("donation_purpose") or doc.get("purpose_of_donation") or "-" }}
										{% endif %}
									</td>
								</tr>

								<tr>
									<td class="receipt-label">Remarks:</td>
									<td class="receipt-value receipt-small">{{ remarks }}</td>
								</tr>
							</tbody>
						</table>
					</td>

					<td class="receipt-column receipt-column-right">
						<table class="receipt-fields">
							<tbody>
								<tr>
									<td class="receipt-label">Receipt #:</td>
									<td class="receipt-value receipt-value-strong">{{ doc.name }}</td>
								</tr>

								<tr>
									<td class="receipt-label">Code:</td>
									<td class="receipt-value">{{ doc.get("donor_name") or "-" }}</td>
								</tr>

								<tr>
									<td class="receipt-label-wrap">Madaris Quantity:</td>
									<td class="receipt-value">{{ beneficiary_count or "-" }}</td>
								</tr>

								<tr>
									<td class="receipt-label">Payment Type:</td>
									<td class="receipt-value">{{ doc.get("mode_of_payment") or "-" }}</td>
								</tr>

								<tr>
									<td class="receipt-label">Amount:</td>
									<td class="receipt-value receipt-amount">
										{% if currency == "PKR" %}
											Rs {{ frappe.utils.fmt_money(amount, precision=2) }}
										{% else %}
											{{ frappe.utils.fmt_money(amount, precision=2, currency=currency) }}
										{% endif %}
									</td>
								</tr>

								<tr>
									<td class="receipt-label">Rupees:</td>
									<td class="receipt-value receipt-small">
										{{ frappe.utils.money_in_words(amount, currency) }}
									</td>
								</tr>
							</tbody>
						</table>
					</td>
				</tr>
			</tbody>
		</table>
	</div>
</div>
